insert into query_messages (id, query_id, author_id, body) values
  ('71000001-0000-0000-0000-000000002401','70000001-0000-0000-0000-000000002401','10000000-0000-0000-0000-000000000001','Litter moisture recorded as Wet with caking present at D14. Wet litter raises footpad-dermatitis and ammonia risk — confirm the reading, check for drinker leaks, and document the corrective action.'),
  ('71000002-0000-0000-0000-000000002401','70000002-0000-0000-0000-000000002401','10000000-0000-0000-0000-000000000001','Auto edit-check: Computed period FCR is above the broiler performance range (1.50–1.80; soft alert above 1.90) — verify the pen weight and feed weigh-back entries and investigate feed wastage or sub-optimal flock health.'),
  ('71000001-0000-0000-0000-000000002502','70000001-0000-0000-0000-000000002502','10000000-0000-0000-0000-000000000001','Auto edit-check: Rectal temperature 40.6 °C exceeds the bovine range (38.0–39.3 °C) — consistent with a febrile BRD episode; confirm against source and the screening reading.'),
  ('71000002-0000-0000-0000-000000002502','70000002-0000-0000-0000-000000002502','10000000-0000-0000-0000-000000000001','Day-3 heart rate of 72 bpm is at the low end versus the Day-0 reading for this animal. Confirm the chute-side count against the source worksheet.'),
  ('71000003-0000-0000-0000-000000002502','70000002-0000-0000-0000-000000002502','10000000-0000-0000-0000-000000000001','Re-counted at the chute — 72 bpm is correct; the animal had settled and the Day-0 reading was elevated by handling stress. Value confirmed.'),
  ('71000001-0000-0000-0000-000000000801','70000001-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Resting heart rate of 96 bpm is higher than the typical resting range for this patient. Confirm the dog was settled at the time of measurement.'),
  ('71000002-0000-0000-0000-000000000801','70000002-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Respiratory rate of 20/min recorded during an excited exam — confirm whether this was a true resting measurement.'),
  ('71000003-0000-0000-0000-000000000801','70000002-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Re-measured after a 5-minute acclimation period; resting respiratory rate confirmed at 20/min. No respiratory abnormality.'),
  ('71000004-0000-0000-0000-000000000801','70000003-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','CADESI-04 of 58 is high relative to the recorded lesion severity (Moderate). Please confirm the lesion scoring against the regional map.'),
  ('71000005-0000-0000-0000-000000000801','70000004-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Otitis externa noted. Confirm whether cytology was performed and whether a secondary infection requires concomitant treatment per protocol.'),
  ('71000006-0000-0000-0000-000000000801','70000004-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Cytology performed — mild Malassezia overgrowth, managed topically; not an exclusionary systemic infection. Documented in the source.'),
  ('71000007-0000-0000-0000-000000000801','70000005-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Baseline owner PVAS of 7.2 is higher than the average of the pre-baseline diary entries (≈5.8). Please confirm the score was transcribed from the correct diary week.'),
  ('71000008-0000-0000-0000-000000000801','70000006-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Baseline CADESI-04 of 58 is identical to the screening value recorded one week earlier. Confirm this was independently re-scored at the baseline visit rather than carried forward.'),
  ('71000009-0000-0000-0000-000000000801','70000006-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Re-scored independently at baseline by the same assessor; score genuinely unchanged at 58. Source confirms two separate assessments.'),
  ('7100000A-0000-0000-0000-000000000801','70000007-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Investigator Global Assessment recorded as 4 (severe) — confirm this aligns with the CADESI-04 regional findings and the lesion photographs.'),
  ('7100000B-0000-0000-0000-000000000801','70000008-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','84 units dispensed for an 84-day supply assumes once-daily dosing. Confirm against the protocol dosing schedule and the dog''s body weight band.'),
  ('7100000C-0000-0000-0000-000000000801','70000008-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Protocol specifies once-daily dosing; 12.4 kg falls in the single-unit band. 84 units = 84 days confirmed correct.'),
  ('7100000D-0000-0000-0000-000000000801','70000008-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Verified against the dosing schedule and dispensation log. Quantity correct — query resolved.'),
  ('7100000E-0000-0000-0000-000000000801','70000009-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Screening weight 31.2 kg differs from the referral record (29.4 kg). Confirm the scale reading and recent weight history.'),
  ('7100000F-0000-0000-0000-000000000801','70000009-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Re-weighed on a calibrated scale at 31.2 kg; owner reports recent weight gain on the current diet. Value confirmed.'),
  ('71000010-0000-0000-0000-000000000801','70000009-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Resolved at study completion — value confirmed correct by investigator.'),
  ('71000011-0000-0000-0000-000000000801','7000000A-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Chronic itching ≥6 months marked Yes. Confirm the referral history documents a pruritus onset date supporting the ≥6-month criterion.'),
  ('71000012-0000-0000-0000-000000000801','7000000A-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Referral letter dated 2025-08 documents pruritus onset ~10 months prior to screening. Criterion met; source filed.'),
  ('71000013-0000-0000-0000-000000000801','7000000A-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Resolved at study completion — value confirmed correct by investigator.'),
  ('71000014-0000-0000-0000-000000000801','7000000B-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Investigator narrative cites a final PVAS of 2.1, but please confirm this matches the Day 84 owner diary entry rather than the clinic-recorded value.'),
  ('71000015-0000-0000-0000-000000000801','7000000B-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Value re-checked against source — confirmed correct.'),
  ('71000016-0000-0000-0000-000000000801','7000000B-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Resolved at study completion — value confirmed correct by investigator.'),
  ('71000017-0000-0000-0000-000000000801','7000000C-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Subject failed on the baseline pruritus criterion (owner PVAS <5). Confirm the screening pruritus score was taken from the validated owner assessment, not a clinic estimate.'),
  ('71000018-0000-0000-0000-000000000801','7000000D-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','CADESI-04 recorded as 22 but the uploaded lesion photographs suggest more extensive truncal involvement. Please re-score against the photo set and confirm.'),
  ('71000019-0000-0000-0000-000000000801','7000000E-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Lesion severity recorded as Moderate while pruritus is Moderate — confirm the lesion grade against the regional examination notes.'),
  ('7100001A-0000-0000-0000-000000000801','7000000F-0000-0000-0000-000000000801','10000000-0000-0000-0000-000000000001','Auto edit-check: Temperature 40.1 °C is above the expected range for dogs (38.3–39.2 °C) — verify the thermometer and re-check the patient for pyrexia.');
